text(await tools.exec_command({cmd:"cat > tmp/cards/race-gate-hold-pairs/design.py <<'PY'\nimport itertools\norigins='send swap bridge node initial-legacy initial-journal legacy-speed legacy-cancel journal-speed journal-cancel restore-speed restore-cancel'.split()\nplans=[]\nfor o in origins:\n for n in 'legacy-speed legacy-cancel journal-speed journal-cancel restore-speed restore-cancel'.split():\n  if o=='node' and not n.startswith('legacy-'): continue\n  for target in ['predecessor','replacement']:\n   for retained in [False,True]: plans.append((o,n,target,retained))\nplans += [('node',n,'predecessor',False) for n in 'initial-legacy initial-journal journal-rejected journal-rejected-cancel restore-conflict restore-rejected-speed restore-rejected-cancel'.split()]\nplans += [(o,n,'predecessor',False) for o in ['send','initial-legacy','initial-journal'] for n in ['initial-legacy','initial-journal']]\nplans += [(o,n,'predecessor',False) for o in origins for n in ['again','recover-again']]\nplans += [(o,'node-restore-noop','predecessor',False) for o in ['swap','bridge']]\nplans += [('restore-'+kind,'node-replacement-upgrade','predecessor',False) for kind in ['speed','cancel']]\ndef dims(p): return [('origin',p[0]),('next',p[1]),('target',p[2]),('retained',p[3])]\nseen=set(); reps=[]\nfor p in plans:\n keys=dims(p)\n if any(k not in seen for k in keys): reps.append(p)\n seen.update(keys)\nprint('first',len(reps),len(reps)*90+(313-len(reps))*2)\nseen=set(); reps=[]\nwhile True:\n best=max(plans,key=lambda p:sum(k not in seen for k in dims(p)))\n if all(k in seen for k in dims(best)): break\n reps.append(best); seen.update(dims(best))\nprint('greedy',len(reps),len(reps)*90+(313-len(reps))*2)\nprint(*reps,sep='\\n')\nPY\npython3 tmp/cards/race-gate-hold-pairs/design.py","workdir":"/Users/ardud/checkouts/race-gate-hold-pairs","max_output_tokens":1600}));
